<?php
if(!defined('ABSPATH'))exit;
function sscwp_find_seed($path){$ids=get_posts(['post_type'=>['page','ssc_product','ssc_news','ssc_customer','wp_template_part'],'post_status'=>'any','fields'=>'ids','numberposts'=>1,'meta_key'=>'_ssc_seed_path','meta_value'=>$path]);return $ids?(int)$ids[0]:0;}
function sscwp_media_files(){return array_values(array_filter(scandir(get_theme_file_path('assets')),fn($f)=>preg_match('/\.(png|jpe?g|webp)$/i',$f)));}
function sscwp_import_skeleton(){
 $seed=sscwp_seed();$routes=get_option('sscwp_route_map',[]);$ids=[];
 foreach($seed['catalog']['categories']as $c){$term=term_exists($c['id'],'ssc_category');if(!$term)$term=wp_insert_term($c['name'],'ssc_category',['slug'=>$c['id'],'description'=>$c['desc']]);if(is_wp_error($term))return $term;$id=(int)$term['term_id'];update_term_meta($id,'_ssc_image',$c['image']);$link=get_term_link($id,'ssc_category');if(!is_wp_error($link))$routes['/produktkategorier/'.$c['id']]=$link;}
 foreach($seed['records']as $i=>$r){if($r['kind']==='category')continue;$path=$r['path'];$id=sscwp_find_seed($path);if(!$id){$id=wp_insert_post(['post_type'=>$r['kind'],'post_status'=>'draft','post_title'=>$r['title'],'post_name'=>$path==='/'?'startsida':basename($path),'menu_order'=>$i],true);if(is_wp_error($id))return $id;update_post_meta($id,'_ssc_seed_path',$path);} $ids[$path]=$id;}
 foreach($seed['records']as $r){if($r['kind']==='category')continue;$path=$r['path'];$id=$ids[$path];if($r['kind']==='page'&&substr_count(trim($path,'/'),'/')>0){$parent=dirname($path);if(isset($ids[$parent]))wp_update_post(['ID'=>$id,'post_parent'=>$ids[$parent]]);} $routes[$path]=get_permalink($id);}
 update_option('sscwp_route_map',$routes,false);update_option('sscwp_post_map',$ids,false);return true;
}
function sscwp_import_media($offset){
 require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';
 $files=sscwp_media_files();$map=get_option('sscwp_media_map',[]);$uploads=wp_upload_dir();if(!empty($uploads['error']))return new WP_Error('uploads',$uploads['error']);
 foreach(array_slice($files,$offset,3)as $file){if(!empty($map[$file])&&get_post($map[$file]))continue;$existing=get_posts(['post_type'=>'attachment','post_status'=>'inherit','numberposts'=>1,'fields'=>'ids','meta_key'=>'_ssc_asset_file','meta_value'=>$file]);if($existing){$map[$file]=$existing[0];continue;}$target=wp_unique_filename($uploads['path'],$file);$dest=$uploads['path'].'/'.$target;if(!copy(get_theme_file_path('assets/'.$file),$dest))return new WP_Error('copy','Kunde inte kopiera bilden '.$file);$type=wp_check_filetype($target);$id=wp_insert_attachment(['post_mime_type'=>$type['type'],'post_title'=>pathinfo($file,PATHINFO_FILENAME),'post_status'=>'inherit'],$dest,0,true);if(is_wp_error($id))return $id;update_post_meta($id,'_ssc_asset_file',$file);$metadata=wp_generate_attachment_metadata($id,$dest);if($metadata)wp_update_attachment_metadata($id,$metadata);$map[$file]=$id;}
 update_option('sscwp_media_map',$map,false);return min($offset+3,count($files));
}
function sscwp_rewrite_blocks($blocks){foreach($blocks as &$b){$a=&$b['attrs'];if(isset($a['url'])&&str_starts_with($a['url'],'assets/'))$a['url']=sscwp_asset($a['url']);if(($b['blockName']??'')==='ssc/image'&&!empty($a['url'])){$file=basename(wp_parse_url($a['url'],PHP_URL_PATH));$map=get_option('sscwp_media_map',[]);foreach($map as $original=>$id)if(wp_get_attachment_url($id)===$a['url']){$a['id']=(int)$id;break;}}
 if(isset($b['innerBlocks']))$b['innerBlocks']=sscwp_rewrite_blocks($b['innerBlocks']);}return $blocks;}
function sscwp_import_record($r,$order=0){if($r['kind']==='category')return true;$id=sscwp_find_seed($r['path']);if(!$id)return new WP_Error('missing','Sidan saknas i importen. Starta importen igen.');if(get_post_meta($id,'_ssc_import_version',true)===SSCWP_VERSION)return true;
 $blocks=sscwp_rewrite_blocks(parse_blocks($r['content']));$content=serialize_blocks($blocks);$result=wp_update_post(wp_slash(['ID'=>$id,'post_content'=>$content,'post_status'=>'publish','menu_order'=>$order]),true);if(is_wp_error($result))return $result;
 update_post_meta($id,'_ssc_description',$r['description']);update_post_meta($id,'_ssc_noindex',$r['noindex']?'1':'0');
 $map=get_option('sscwp_media_map',[]);if(!empty($r['image'])&&!empty($map[$r['image']]))set_post_thumbnail($id,$map[$r['image']]);
 if($r['kind']==='ssc_product'){foreach(sscwp_catalog_data()['products']as $p)if($p['id']===basename($r['path'])){foreach(['brand','desc','variants','benefits','specs','downloads','addons']as $key)update_post_meta($id,'sscwp_'.$key,$p[$key]??[]);wp_set_object_terms($id,$p['categories'],'ssc_category');}}
 update_post_meta($id,'_ssc_import_version',SSCWP_VERSION);$pending=get_option('sscwp_import_pending_paths',[]);$pending[]=$r['path'];update_option('sscwp_import_pending_paths',array_values(array_unique($pending)),false);return true;
}
function sscwp_import_finish($front=true){
 foreach(['header','footer']as $slug){$path='@part/'.$slug;$id=sscwp_find_seed($path);$content=serialize_blocks(sscwp_rewrite_blocks(parse_blocks(sscwp_seed()[$slug])));if(!$id){$id=wp_insert_post(wp_slash(['post_type'=>'wp_template_part','post_status'=>'publish','post_name'=>$slug,'post_title'=>$slug==='header'?'Sidhuvud':'Sidfot','post_content'=>$content]));if(!is_wp_error($id)){wp_set_object_terms($id,get_stylesheet(),'wp_theme');wp_set_object_terms($id,$slug,'wp_template_part_area');update_post_meta($id,'_ssc_seed_path',$path);$pending=get_option('sscwp_parts_pending',[]);$pending[]=$slug;update_option('sscwp_parts_pending',array_values(array_unique($pending)),false);}}}
 if($front){$id=sscwp_find_seed('/');if($id){if(!get_option('sscwp_previous_front'))update_option('sscwp_previous_front',['show_on_front'=>get_option('show_on_front'),'page_on_front'=>get_option('page_on_front')],false);update_option('show_on_front','page');update_option('page_on_front',$id);}}
 if(!get_option('permalink_structure'))update_option('permalink_structure','/%postname%/');flush_rewrite_rules(false);
 $routes=get_option('sscwp_route_map',[]);foreach(get_option('sscwp_post_map',[])as $path=>$id)$routes[$path]=get_permalink($id);foreach(sscwp_catalog_data()['categories']as $c){$term=get_term_by('slug',$c['id'],'ssc_category');if($term){$url=get_term_link($term);if(!is_wp_error($url))$routes['/produktkategorier/'.$c['id']]=$url;}}update_option('sscwp_route_map',$routes,false);
 // Internal links are resolved at render time, using the current WordPress route map.
 delete_option('sscwp_import_pending_paths');delete_option('sscwp_parts_pending');update_option('sscwp_import_complete_210',true,false);return true;
}
add_action('admin_menu',function(){add_theme_page('SSC – kom igång','SSC – kom igång','manage_options','sscwp-setup','sscwp_setup_page');});
function sscwp_setup_page(){if(!current_user_can('manage_options'))return; ?>
<div class="wrap"><h1>SSC – kom igång</h1><p>Importera webbplatsen som redigerbara WordPress-block, med produktregister och bilder i mediabiblioteket.</p><p><strong>Ta en säkerhetskopia om webbplatsen redan innehåller material.</strong> Importen skapar nya poster och skriver inte över andra sidor. Om samma namn redan finns kan WordPress lägga till ”-2” i adressen. Avbruten import kan fortsätta; redan importerade bilder och innehåll hoppas över.</p><p>Detta paket är avsett för en ny installation eller en testkopia. Om ett äldre SSC-tema redan har importerats, testa först i en kopia så att dubbla produktregister eller tidigare anpassningar upptäcks.</p><label><input id="ssc-front" type="checkbox" checked> Använd SSC:s startsida som webbplatsens startsida</label><p><button id="ssc-import" class="button button-primary">Importera SSC-webbplatsen</button></p><progress id="ssc-progress" max="100" value="0" style="width:420px;max-width:100%"></progress><p id="ssc-status" role="status"></p><p>Efter import: redigera sidor under <strong>Sidor</strong>, produkter under <strong>Produkter</strong> och sidhuvud/sidfot under <strong>Utseende → Redigerare</strong>. Produktblad och manualer läggs till i produktens panel <strong>SSC produktdata</strong>.</p></div>
<script>
(()=>{const button=document.getElementById('ssc-import'),status=document.getElementById('ssc-status'),progress=document.getElementById('ssc-progress');button.onclick=async()=>{button.disabled=true;let stage='skeleton',offset=0;try{while(stage!=='done'){status.textContent='Importerar: '+({skeleton:'förbereder sidor',media:'bilder',content:'block och produkter',finish:'menyer och inställningar'}[stage]||stage)+'…';const body=new URLSearchParams({action:'sscwp_import',nonce:<?php echo wp_json_encode(wp_create_nonce('sscwp_import')); ?>,stage,offset:String(offset),front:document.getElementById('ssc-front').checked?'1':'0'});const response=await fetch(ajaxurl,{method:'POST',body});const result=await response.json();if(!result.success)throw Error(result.data?.message||'Importen avbröts');({stage,offset}=result.data);progress.value=result.data.progress;}status.textContent='Klart! Webbplatsen är importerad. Du kan nu redigera sidor, bilder och produkter.';}catch(e){status.textContent='Importen pausades: '+e.message+'. Klicka på knappen för att fortsätta.';}finally{button.disabled=false}}})();
</script>
<?php }
add_action('wp_ajax_sscwp_import',function(){if(!current_user_can('manage_options'))wp_send_json_error(['message'=>'Behörighet saknas'],403);check_ajax_referer('sscwp_import','nonce');$stage=sanitize_key($_POST['stage']??'');$offset=max(0,(int)($_POST['offset']??0));$records=sscwp_seed()['records'];$result=true;$progress=0;
 if($stage==='skeleton'){$result=sscwp_import_skeleton();$stage='media';$offset=0;$progress=5;}
 elseif($stage==='media'){$result=sscwp_import_media($offset);if(!is_wp_error($result)){$offset=$result;$progress=5+40*$offset/max(1,count(sscwp_media_files()));if($offset>=count(sscwp_media_files())){$stage='content';$offset=0;}}}
 elseif($stage==='content'){foreach(array_slice($records,$offset,4)as $i=>$r){$result=sscwp_import_record($r,$offset+$i);if(is_wp_error($result))break;}$offset=min($offset+4,count($records));$progress=45+50*$offset/count($records);if($offset>=count($records)){$stage='finish';$offset=0;}}
 elseif($stage==='finish'){$result=sscwp_import_finish(!empty($_POST['front']));$stage='done';$progress=100;}else wp_send_json_error(['message'=>'Okänt importsteg'],400);
 if(is_wp_error($result))wp_send_json_error(['message'=>$result->get_error_message()],500);wp_send_json_success(['stage'=>$stage,'offset'=>$offset,'progress'=>$progress]);
});
